action.command:
python3 - <<'PY'
import json
p='/workspace/contracts/openapi.contract.json'; d=json.load(open(p))
for path, ms in d['paths'].items():
 for method,op in ms.items():
  if method.startswith('x-'): continue
  print('\n###',method.upper(),path,op['operationId'])
  for prm in op.get('parameters',[]): print('PARAM',prm['name'],prm.get('in'),prm.get('required'),prm.get('schema'))
  rb=op.get('requestBody');
  if rb:
   print('REQ',json.dumps(rb.get('content',{}).get('application/json',{}).get('schema',{}),separators=(',',':')))
  for code,r in op.get('responses',{}).items():
   if code in ('200','201'):
    print('RES',code,json.dumps(r.get('content',{}).get('application/json',{}).get('schema',{}),separators=(',',':')))
print('\nSCHEMAS')
for n,s in d['components']['schemas'].items(): print(n,json.dumps(s,separators=(',',':')))
PY

