package main

import (
 "crypto/rand"
 "encoding/hex"
 "encoding/json"
 "fmt"
 "io"
 "log"
 "net/http"
 "os"
 "path/filepath"
 "strconv"
 "strings"
 "sync"
 "time"
)

type User struct { ID, Username, Password, Email, FullName, Phone string; Roles, Qualifications []string; Certifications []map[string]any; Active bool; AssignedLocationID, ActiveRole string }
type Store struct { Users map[string]User `json:"users"`; Locations map[string]map[string]any `json:"locations"`; Connections map[string]map[string]any `json:"connections"`; SampleTypes map[string]map[string]any `json:"sampleTypes"`; Requests map[string]map[string]any `json:"requests"`; Samples map[string]map[string]any `json:"samples"`; Journeys map[string]map[string]any `json:"journeys"`; Assignments map[string]map[string]any `json:"assignments"`; Handoffs map[string]map[string]any `json:"handoffs"`; Audit []map[string]any `json:"audit"`; NextEvent int64 `json:"nextEvent"` }
type App struct { mu sync.Mutex; s Store; sessions map[string]string; path string }

func uid() string { b:=make([]byte,16); _,_=rand.Read(b); b[6]=(b[6]&15)|64; b[8]=(b[8]&63)|128; return fmt.Sprintf("%s-%s-%s-%s-%s",hex.EncodeToString(b[:4]),hex.EncodeToString(b[4:6]),hex.EncodeToString(b[6:8]),hex.EncodeToString(b[8:10]),hex.EncodeToString(b[10:])) }
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func str(m map[string]any,k string) string { if v,ok:=m[k].(string);ok{return v}; return "" }
func boolv(m map[string]any,k string, d bool) bool { if v,ok:=m[k].(bool);ok{return v}; return d }
func num(m map[string]any,k string) float64 { if v,ok:=m[k].(float64);ok{return v}; return 0 }
func (a *App) save() { b,_:=json.MarshalIndent(a.s,"","  "); tmp:=a.path+".tmp"; _=os.WriteFile(tmp,b,0600); _=os.Rename(tmp,a.path) }
func (a *App) load() { b,e:=os.ReadFile(a.path); if e==nil { _=json.Unmarshal(b,&a.s) }; if a.s.Users==nil {a.s.Users=map[string]User{}}; if a.s.Locations==nil {a.s.Locations=map[string]map[string]any{}}; if a.s.Connections==nil {a.s.Connections=map[string]map[string]any{}}; if a.s.SampleTypes==nil {a.s.SampleTypes=map[string]map[string]any{}}; if a.s.Requests==nil {a.s.Requests=map[string]map[string]any{}}; if a.s.Samples==nil {a.s.Samples=map[string]map[string]any{}}; if a.s.Journeys==nil {a.s.Journeys=map[string]map[string]any{}}; if a.s.Assignments==nil {a.s.Assignments=map[string]map[string]any{}}; if a.s.Handoffs==nil {a.s.Handoffs=map[string]map[string]any{}}; if a.s.NextEvent==0 {a.s.NextEvent=1} }
func (a *App) seed() { if len(a.s.SampleTypes)>0{return}; for _,x:=range []struct{n,c string; min,max float64; cool,batch bool}{ {"Amber","standard",15,30,false,true},{"Indigo","standard",15,30,false,true},{"Frost","cooled",2,8,true,true},{"Pulse","standard",15,30,false,false} } { id:=uid(); a.s.SampleTypes[id]=map[string]any{"sampleTypeId":id,"name":x.n,"qualifiedCollectorRequired":true,"requiredQualification":x.n,"containerType":x.c,"temperatureMinC":x.min,"temperatureMaxC":x.max,"incompatibleSampleTypes":[]string{},"requiresCooledRoute":x.cool,"batchingAllowed":x.batch} } }
func (a *App) ensureAdmin() { if len(a.s.Users)>0{return}; id:=uid(); a.s.Users[id]=User{ID:id,Username:os.Getenv("ADMIN_USERNAME"),Password:os.Getenv("ADMIN_PASSWORD"),FullName:"System Administrator",Roles:[]string{"administrator"},Active:true,ActiveRole:"administrator"}; if a.s.Users[id].Username=="" {a.s.Users[id]=User{ID:id,Username:"admin",Password:"admin",FullName:"System Administrator",Roles:[]string{"administrator"},Active:true,ActiveRole:"administrator"}}; a.save() }
func write(w http.ResponseWriter,status int,v any){w.Header().Set("content-type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
func ok(w http.ResponseWriter,status int,d any){write(w,status,map[string]any{"data":d})}
func fail(w http.ResponseWriter,status int,code,msg string){write(w,status,map[string]any{"error":msg,"code":code})}
func decode(r *http.Request) map[string]any { b,_:=io.ReadAll(r.Body); var m map[string]any; _=json.Unmarshal(b,&m); if m==nil {m=map[string]any{}}; return m }
func (a *App) actor(r *http.Request) (User,bool) { t:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer "); id,ok:=a.sessions[t]; if !ok{return User{},false}; u,ok:=a.s.Users[id]; return u,ok&&u.Active }
func has(u User, role string) bool {for _,x:=range u.Roles{if x==role{return true}};return false}
func (a *App) audit(u User, action, typ,id string, success bool, details any){a.s.Audit=append(a.s.Audit,map[string]any{"auditId":uid(),"actorId":u.ID,"role":u.ActiveRole,"actorRole":u.ActiveRole,"action":action,"entityType":typ,"entityId":id,"success":success,"occurredAt":now(),"details":details})}
func timeline(a *App,u User,action,typ,id string) map[string]any {a.s.NextEvent++; return map[string]any{"eventId":a.s.NextEvent,"action":action,"actorId":u.ID,"role":u.ActiveRole,"entityType":typ,"entityId":id,"success":true,"occurredAt":now(),"details":map[string]any{}}}
func coord(m map[string]any) map[string]any {if x,ok:=m["origin"].(map[string]any);ok{return x}; return map[string]any{"latitude":0,"longitude":0}}
func (a *App) service(m map[string]any) map[string]any { origin:=coord(m); best:=""; reason:="outside_service_coverage"; for id,l:=range a.s.Locations { f,_:=l["functions"].(map[string]any); if boolv(l,"active",false)&&boolv(f,"collection_point",false){best=id;reason="no_accepting_laboratory";break} }; for id,l:=range a.s.Locations {f,_:=l["functions"].(map[string]any); if boolv(l,"active",false)&&boolv(f,"laboratory",false){best=id;reason="serviceable";break} }; out:=map[string]any{"serviceable":reason=="serviceable","reason":reason,"serviceabilityVersion":1}; if best!="" {out["targetLaboratoryId"]=best}; _=origin; return out }

func (a *App) handle(w http.ResponseWriter,r *http.Request){
 if r.URL.Path=="/ready" {write(w,http.StatusOK,map[string]string{"status":"ready"});return}
 if r.URL.Path=="/" {http.ServeFile(w,r,"web/index.html");return}
 if r.URL.Path=="/api/ui/bootstrap" {a.mu.Lock(); defer a.mu.Unlock(); locations:=[]map[string]any{};for _,x:=range a.s.Locations{locations=append(locations,x)}; types:=[]map[string]any{};for _,x:=range a.s.SampleTypes{types=append(types,x)}; ok(w,200,map[string]any{"locations":locations,"sampleTypes":types,"roles":[]string{"administrator","dispatcher","requester","collection_professional","delivery_partner","node_handler","laboratory_team"}});return}
 if r.URL.Path=="/api/authenticate-user" {m:=decode(r);a.mu.Lock();defer a.mu.Unlock();for _,u:=range a.s.Users{if u.Username==str(m,"username")&&u.Password==str(m,"password")&&u.Active {t:=uid();a.sessions[t]=u.ID;a.audit(u,"sign_in","user",u.ID,true,nil);a.save();ok(w,200,map[string]any{"sessionToken":t,"userId":u.ID,"roles":u.Roles,"activeRole":u.ActiveRole});return}};fail(w,401,"invalid_credentials","Invalid username or password");return}
 if r.Method=="GET"&&strings.HasPrefix(r.URL.Path,"/api/read-sample-state/"){u,ok1:=a.actor(r);if !ok1{fail(w,401,"unauthorized","Authentication required");return};id:=strings.TrimPrefix(r.URL.Path,"/api/read-sample-state/");a.mu.Lock();defer a.mu.Unlock();s,ok2:=a.s.Samples[id];if !ok2{fail(w,404,"not_found","Sample not found");return};if !has(u,"administrator")&&!has(u,"dispatcher")&&str(s,"requesterId")!=u.ID{fail(w,403,"forbidden","Not permitted");return};ok(w,200,a.sampleState(s));return}
 u,aut:=a.actor(r);if !aut{fail(w,401,"unauthorized","Authentication required");return}; m:=decode(r); op:=strings.TrimPrefix(r.URL.Path,"/api/"); a.mu.Lock(); defer a.mu.Unlock()
 switch op {
 case "check-serviceability": ok(w,200,a.service(m)); return
 case "read-serviceability-snapshot": ok(w,200,map[string]any{"version":1,"publishedAt":now(),"regions":a.regions()});return
 case "create-location": id:=uid(); f:=map[string]any{};for _,x:=range arr(m,"functions"){f[x]=true}; l:=map[string]any{"locationId":id,"name":str(m,"name"),"coordinate":coord(m),"coverageKm":5.0,"handlingMinutes":0,"active":boolv(m,"active",true),"functions":f};a.s.Locations[id]=l;a.audit(u,"create_location","location",id,true,l);a.save();ok(w,201,l);return
