package main

import (
 "crypto/rand"
 "encoding/hex"
 "encoding/json"
 "fmt"
 "io"
 "log"
 "net/http"
 "os"
 "path/filepath"
 "strconv"
 "strings"
 "sync"
 "time"
)

type User struct { ID, Username, Password, Email, FullName, Phone string; Roles, Qualifications []string; Certifications []map[string]any; Active bool; AssignedLocationID, ActiveRole string }
type Store struct { Users map[string]User `json:"users"`; Locations map[string]map[string]any `json:"locations"`; Connections map[string]map[string]any `json:"connections"`; SampleTypes map[string]map[string]any `json:"sampleTypes"`; Requests map[string]map[string]any `json:"requests"`; Samples map[string]map[string]any `json:"samples"`; Journeys map[string]map[string]any `json:"journeys"`; Assignments map[string]map[string]any `json:"assignments"`; Handoffs map[string]map[string]any `json:"handoffs"`; Audit []map[string]any `json:"audit"`; NextEvent int64 `json:"nextEvent"` }
type App struct { mu sync.Mutex; s Store; sessions map[string]string; path string }

func uid() string { b:=make([]byte,16); _,_=rand.Read(b); b[6]=(b[6]&15)|64; b[8]=(b[8]&63)|128; return fmt.Sprintf("%s-%s-%s-%s-%s",hex.EncodeToString(b[:4]),hex.EncodeToString(b[4:6]),hex.EncodeToString(b[6:8]),hex.EncodeToString(b[8:10]),hex.EncodeToString(b[10:])) }
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func str(m map[string]any,k string) string { if v,ok:=m[k].(string);ok{return v}; return "" }
func boolv(m map[string]any,k string, d bool) bool { if v,ok:=m[k].(bool);ok{return v}; return d }
